"use client";

import { ChevronDownIcon } from "lucide-react";
import { Button, type ButtonProps } from "@/components/ui/button";
import { cn } from "@/lib/utils";

export interface FilterTriggerProps extends ButtonProps {
  /** Emphasises the pill when the filter holds a value. */
  active?: boolean;
  /**
   * The dimension being filtered, shown muted ahead of the value. Omit it when
   * the value names its own dimension — a date range reads as "Last 24h", and
   * "Period: Last 24h" only repeats itself.
   */
  label?: string;
  /**
   * A non-default operator, read as part of the label: "Currency is not:".
   * The default (`is`) goes unsaid, as in Notion.
   */
  operator?: string | null;
  /**
   * The pill offers an X in place of its chevron on hover and keyboard focus.
   * Only the chevron's half of the swap lives here; the X is a sibling, in
   * `PillShell`, because a button inside this button would be invalid.
   */
  removable?: boolean;
}

/**
 * A filter pill: `Action: Deposit`, with a chevron.
 *
 * Written once rather than inlined at each call site for three reasons, none
 * of them purely cosmetic. The muted label is what separates the dimension
 * from the value at a glance. The `active` treatment is what lets you scan a
 * row of eight pills for the two that are doing something. And the chevron is
 * the one the trigger primitives disagree about — `DropdownMenuTrigger` draws
 * none, `SelectTrigger` and `ComboboxTrigger` each draw their own — so putting
 * it here is what stops a row of pills from disagreeing about its own
 * affordance depending on which primitive each one happens to use.
 *
 * Used through `render`, which is how the rest of the block composes triggers:
 *
 * ```tsx
 * <DropdownMenuTrigger render={<FilterTrigger label="Action" />}>
 *   Deposit
 * </DropdownMenuTrigger>
 * ```
 */
/**
 * The swap, in both halves. A removable pill shows its X — and hides its
 * chevron — under two conditions: pointer over the pill, or keyboard focus on
 * it. In neither case while its popup is open, where the chevron is still
 * saying what the click did.
 *
 * Each condition is one compound variant rather than a show rule plus a "not
 * while open" override: two variants of equal specificity settle by stylesheet
 * order, and Tailwind does not promise that order. `hover:` is already gated to
 * devices that can hover (`base.css`), which is what keeps the X off touch
 * screens.
 *
 * The X also turns in from -45° as it grows, so it reads as the chevron
 * turning into an X rather than one icon cross-fading over another.
 *
 * Written out literally, every class in full, because Tailwind finds classes
 * by scanning source text — a variant joined onto a utility at runtime would
 * never be generated.
 */
const CHEVRON_SWAP =
  "transition-[opacity,scale] duration-(--duration-fast) ease-(--ease-ks-out) group-hover/pill:group-not-has-[[aria-expanded=true]]/pill:scale-75 group-hover/pill:group-not-has-[[aria-expanded=true]]/pill:opacity-0 group-has-[[data-filter-pill]:focus-visible]/pill:group-not-has-[[aria-expanded=true]]/pill:scale-75 group-has-[[data-filter-pill]:focus-visible]/pill:group-not-has-[[aria-expanded=true]]/pill:opacity-0";

export const X_SWAP =
  "pointer-events-none -rotate-45 scale-75 opacity-0 transition-[opacity,scale,rotate,background-color] duration-(--duration-fast) ease-(--ease-ks-out) group-hover/pill:group-not-has-[[aria-expanded=true]]/pill:pointer-events-auto group-hover/pill:group-not-has-[[aria-expanded=true]]/pill:rotate-0 group-hover/pill:group-not-has-[[aria-expanded=true]]/pill:scale-100 group-hover/pill:group-not-has-[[aria-expanded=true]]/pill:opacity-100 group-has-[[data-filter-pill]:focus-visible]/pill:group-not-has-[[aria-expanded=true]]/pill:pointer-events-auto group-has-[[data-filter-pill]:focus-visible]/pill:group-not-has-[[aria-expanded=true]]/pill:rotate-0 group-has-[[data-filter-pill]:focus-visible]/pill:group-not-has-[[aria-expanded=true]]/pill:scale-100 group-has-[[data-filter-pill]:focus-visible]/pill:group-not-has-[[aria-expanded=true]]/pill:opacity-100";

export function FilterTrigger({
  active = false,
  children,
  className,
  label,
  operator,
  removable = false,
  ...props
}: FilterTriggerProps) {
  return (
    <Button
      className={cn(
        "gap-1.5",
        // No border or ring for the applied state. Anything bright enough to
        // scan a row of pills for reads as focus, which is a control claiming
        // the keyboard is on it. The distinction lives in the value instead:
        // an unset pill renders its "All" muted, a set one renders its value
        // at full strength — the same way a placeholder differs from an entry.
        className
      )}
      data-active={active || undefined}
      // Not `data-slot`: used through `render`, the trigger primitive merges
      // its own props over this element's and stamps its own slot, so a
      // `data-slot` here is silently discarded. This attribute is the one
      // thing that can identify a pill in the DOM.
      data-filter-label={label}
      data-filter-pill=""
      size="sm"
      variant="outline"
      {...props}
    >
      {label ? (
        <span className="font-normal text-muted-foreground" data-pill-label="">
          {operator ? `${label} ${operator}:` : `${label}:`}
        </span>
      ) : null}
      {children}
      <ChevronDownIcon
        className={cn("text-muted-foreground", removable && CHEVRON_SWAP)}
      />
    </Button>
  );
}

"use client";

import { XIcon } from "lucide-react";
import type { KeyboardEvent, ReactNode } from "react";
import { useRef, useSyncExternalStore } from "react";
import { X_SWAP } from "@/components/filter-trigger";
import { cn } from "@/lib/utils";

export interface ShellControls {
  /** Backspace / Delete on the trigger removes the filter. */
  keyDown: (event: KeyboardEvent<HTMLElement>) => void;
  remove: () => void;
}

/**
 * Wraps a pill's trigger with the X that swaps in for its chevron.
 *
 * The X is the trigger's sibling, not its child: a button inside a button is
 * invalid HTML and leaves the inner one unreachable to assistive tech. It sits
 * absolutely over the chevron's 16px slot — `end-3` is the `sm` button's `px-3`
 * — so showing it changes nothing about the pill's width.
 *
 * It is out of the tab order. Keyboard users have Backspace on the trigger,
 * which is announced through `aria-keyshortcuts`; one stop per pill keeps
 * tabbing along a row of eight pills at eight stops rather than sixteen.
 *
 * Every pill has one, the starting pair included, so the X means the same
 * thing wherever it appears. The label says which filter, "Remove Provider
 * filter", for the same reason the row actions do.
 */
export function PillShell({
  children,
  label,
  onRemove,
}: {
  children: (controls: ShellControls) => ReactNode;
  /** The filter's dimension, for the X's accessible name. */
  label: string;
  /** Handed the pill's trigger, so focus can move before it unmounts. */
  onRemove: (trigger: HTMLElement | null) => void;
}) {
  const ref = useRef<HTMLSpanElement>(null);
  const remove = () =>
    onRemove(
      ref.current?.querySelector<HTMLElement>("[data-filter-pill]") ?? null
    );
  const keyDown = (event: KeyboardEvent<HTMLElement>) => {
    if (
      (event.key === "Backspace" || event.key === "Delete") &&
      !event.defaultPrevented &&
      event.currentTarget.getAttribute("aria-expanded") !== "true"
    ) {
      event.preventDefault();
      remove();
    }
  };

  return (
    <span className="group/pill relative inline-flex" ref={ref}>
      {children({ keyDown, remove })}
      <button
        aria-label={`Remove ${label} filter`}
        className={cn(
          "absolute end-3 top-1/2 z-10 grid size-4 -translate-y-1/2 cursor-pointer place-items-center rounded-sm text-muted-foreground before:absolute before:-inset-1 hover:bg-foreground/10 hover:text-foreground",
          X_SWAP
        )}
        data-filter-remove=""
        onClick={remove}
        tabIndex={-1}
        type="button"
      >
        <XIcon className="size-3.5" />
      </button>
    </span>
  );
}

/**
 * The pill's value, in its own slot so the set and unset cases are the same
 * element rather than a span and a bare text node — which is what lets a test
 * compare their colours at all.
 */
export function PillValue({
  empty,
  value,
}: {
  empty: string;
  value: string | null;
}) {
  return (
    <span
      className={value === null ? "font-normal text-muted-foreground" : ""}
      data-pill-value=""
    >
      {value ?? empty}
    </span>
  );
}

const HOVERLESS = "(hover: none)";

/**
 * Whether the device has no hover, and so never sees the X swap.
 *
 * Local to the block rather than `@keystoneui/react/hooks`: blocks install as
 * copies, and that subpath has no registry item to land at. The usual objection
 * to a media-query hook — it has to guess on the server and flip after
 * hydration — does not bite here, because its only callers render inside a
 * popup, which mounts on open, long after hydration.
 */
export function useHoverless(): boolean {
  return useSyncExternalStore(
    (onChange) => {
      const query = matchMedia(HOVERLESS);
      query.addEventListener("change", onChange);
      return () => query.removeEventListener("change", onChange);
    },
    () => matchMedia(HOVERLESS).matches,
    () => false
  );
}

"use client";

import { PlusIcon, TrashIcon } from "lucide-react";
import { type ReactNode, useRef, useState } from "react";
import { Bound } from "@/components/drawer-parts";
import { FilterTrigger } from "@/components/filter-trigger";
import { PillShell, PillValue, useHoverless } from "@/components/pill-shell";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";

/**
 * The pill row's parts, shared by both tables.
 *
 * Each table owns its filter vocabulary — `payment-filters.ts`,
 * `admin-filters.ts` — and composes these with it. Nothing here knows what a
 * payment or a user is, which is what lets the two toolbars be one design
 * rather than two that drift.
 */

export interface PillOption {
  label: string;
  value: string;
}

/** What every pill takes, whatever it opens. */
interface PillBase {
  /**
   * Mount with the popup already open. Set on the pill just added from
   * `+ Add filter`: you picked "Status" because you want to filter by status,
   * so making you click the new pill as well is a wasted step. Read once, on
   * mount — after that the popup is the pill's own business.
   */
  autoOpen?: boolean;
  /** What the pill reads when nothing is set: "All" for a set, "Any" for a range. */
  empty: string;
  /** The dimension, shown muted ahead of the value. */
  label: string;
  /** Takes the pill off the row. Handed its trigger, for focus. */
  onRemove: (trigger: HTMLElement | null) => void;
  /** The value as the pill reads it, or `null` when the filter is unset. */
  value: string | null;
}

/**
 * A single-select filter — `Status: Failed`.
 *
 * Its X takes the chevron's slot on hover and keyboard focus, so the pill never
 * changes width, and Backspace removes it from the keyboard. Touch screens have
 * no hover, so their way off is a "Delete filter" row in the menu.
 *
 * Picking `All` never takes a pill off the row: removing the control from under
 * the cursor mid-interaction is worse than a pill that reads `All`. Removal is
 * always its own, explicit action.
 */
export function OptionPill({
  autoOpen = false,
  empty,
  label,
  onRemove,
  onSelect,
  options,
  selected,
  value,
}: PillBase & {
  onSelect: (value: string) => void;
  options: readonly PillOption[];
  /** The selected option's `value`, which the radio group checks. */
  selected: string;
}) {
  return (
    <PillShell label={label} onRemove={onRemove}>
      {({ keyDown, remove }) => (
        <DropdownMenu defaultOpen={autoOpen}>
          <DropdownMenuTrigger
            render={
              <FilterTrigger
                active={value !== null}
                label={label}
                onKeyDown={keyDown}
                removable
              />
            }
          >
            {/* Unset reads as a placeholder rather than a value, which is what
                separates the pills doing something from those merely present. */}
            <PillValue empty={empty} value={value} />
          </DropdownMenuTrigger>
          <DropdownMenuContent
            align="start"
            className="min-w-44"
            size="compact"
          >
            <DropdownMenuGroup>
              <DropdownMenuRadioGroup onValueChange={onSelect} value={selected}>
                {options.map((option) => (
                  <DropdownMenuRadioItem
                    key={option.value}
                    value={option.value}
                  >
                    {option.label}
                  </DropdownMenuRadioItem>
                ))}
              </DropdownMenuRadioGroup>
            </DropdownMenuGroup>
            <TouchDeleteItem onRemove={remove} />
          </DropdownMenuContent>
        </DropdownMenu>
      )}
    </PillShell>
  );
}

/**
 * A date range needs two fields at once, so it opens a `Popover` rather than a
 * menu. A menu is a list of choices; a pair of bounds is a tiny form.
 */
export function DateRangePill({
  after,
  autoOpen = false,
  before,
  empty,
  id,
  label,
  onAfterChange,
  onBeforeChange,
  onClear,
  onRemove,
  value,
}: PillBase & {
  after: string;
  before: string;
  /** Prefixes the two fields' ids, which must be unique on the page. */
  id: string;
  onAfterChange: (value: string) => void;
  onBeforeChange: (value: string) => void;
  onClear: () => void;
}) {
  const touch = useHoverless();

  return (
    <PillShell label={label} onRemove={onRemove}>
      {({ keyDown, remove }) => (
        <Popover defaultOpen={autoOpen}>
          <PopoverTrigger
            render={
              <FilterTrigger
                active={value !== null}
                label={label}
                onKeyDown={keyDown}
                removable
              />
            }
          >
            <PillValue empty={empty} value={value} />
          </PopoverTrigger>
          <PopoverContent align="start" className="w-72">
            <div className="flex flex-col gap-3">
              <div className="grid grid-cols-2 gap-3">
                <Bound
                  id={`${id}-min`}
                  // From / To, not After / Before: both ends are inclusive,
                  // and "After 1 Jul" would read as excluding the 1st.
                  label="From"
                  onChange={onAfterChange}
                  type="date"
                  value={after}
                />
                <Bound
                  id={`${id}-max`}
                  label="To"
                  onChange={onBeforeChange}
                  type="date"
                  value={before}
                />
              </div>
              {value !== null && (
                <div className="flex justify-end">
                  <Button onClick={onClear} size="xs" variant="ghost">
                    Clear
                  </Button>
                </div>
              )}
              {/* The popover's version of `TouchDeleteItem`. */}
              {touch && (
                <Button
                  className="w-full justify-start text-destructive"
                  onClick={remove}
                  variant="ghost"
                >
                  <TrashIcon />
                  Delete filter
                </Button>
              )}
            </div>
          </PopoverContent>
        </Popover>
      )}
    </PillShell>
  );
}

/**
 * The touch screen's way to remove a pill: no hover means no X, so the menu
 * carries a "Delete filter" row instead.
 *
 * Only on devices that cannot hover: on a pointer device it would be a second
 * copy of the X.
 */
function TouchDeleteItem({ onRemove }: { onRemove: () => void }) {
  const touch = useHoverless();
  if (!touch) {
    return null;
  }

  return (
    <>
      <DropdownMenuSeparator />
      <DropdownMenuItem onClick={onRemove} variant="destructive">
        <TrashIcon />
        Delete filter
      </DropdownMenuItem>
    </>
  );
}

/** The `+ Add filter` menu, holding whatever is not already on the toolbar. */
export function AddFilterMenu<K extends string>({
  items,
  onAdd,
}: {
  items: readonly { key: K; label: string }[];
  onAdd: (key: K) => void;
}): ReactNode {
  const picked = useRef(false);

  if (items.length === 0) {
    return null;
  }

  return (
    <DropdownMenu>
      {/* A lucide `Plus` rather than a literal "+": next to the `X` on Clear
          all, a text glyph would sit at a different weight and baseline. */}
      <DropdownMenuTrigger
        render={<Button data-add-filter="" size="sm" variant="ghost" />}
      >
        <PlusIcon />
        Add filter
      </DropdownMenuTrigger>
      <DropdownMenuContent
        align="start"
        className="min-w-44"
        // Picking a filter opens that filter's own popup, which takes focus;
        // returning it to this button would pull it straight back out. Closed
        // any other way — Escape, a click outside — focus comes home as usual.
        finalFocus={() => {
          const wasPick = picked.current;
          picked.current = false;
          return !wasPick;
        }}
        size="compact"
      >
        <DropdownMenuGroup>
          {items.map((item) => (
            <DropdownMenuItem
              key={item.key}
              onClick={() => {
                picked.current = true;
                onAdd(item.key);
              }}
            >
              {item.label}
            </DropdownMenuItem>
          ))}
        </DropdownMenuGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

/**
 * The row's add and remove, with the focus handling both need.
 *
 * Adding remembers which pill to mount open. Removing unmounts the element
 * holding focus, which would drop focus to <body> — a keyboard user's place in
 * the page, gone. So the target is picked *before* the removal: the next pill
 * along, or, past the last one, `Add filter`, which is where the removed filter
 * has just gone back to.
 */
export function usePillRow<K extends string>({
  onAdd,
  onRemove,
}: {
  onAdd: (key: K) => void;
  onRemove: (key: K) => void;
}) {
  const rowRef = useRef<HTMLDivElement>(null);
  // The filter most recently picked from `+ Add filter`, whose pill mounts open.
  const [opening, setOpening] = useState<K | null>(null);

  const add = (key: K) => {
    setOpening(key);
    onAdd(key);
  };

  const remove = (key: K, trigger: HTMLElement | null) => {
    const row = rowRef.current;
    const all = [
      ...(row?.querySelectorAll<HTMLElement>("[data-filter-pill]") ?? []),
    ];
    const next = all[all.indexOf(trigger as HTMLElement) + 1] ?? null;
    onRemove(key);
    // After the commit, and after Base UI has run its own focus return to a
    // trigger that no longer exists.
    requestAnimationFrame(() => {
      const target = next?.isConnected
        ? next
        : row?.querySelector<HTMLElement>("[data-add-filter]");
      target?.focus();
    });
  };

  return { add, opening, remove, rowRef };
}

"use client";

import {
  ArrowLeftIcon,
  ChevronDownIcon,
  ChevronRightIcon,
  DownloadIcon,
  XIcon,
} from "lucide-react";
import { type ReactNode, useEffect, useState } from "react";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import {
  Drawer,
  DrawerContent,
  DrawerHeader,
  DrawerTitle,
} from "@/components/ui/drawer";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";

/**
 * The parts both of this block's filter drawers are built from.
 *
 * Shared *within* the block, not across blocks. A block installs as one unit,
 * so a file here collides with nothing and costs a consumer nothing — where a
 * file shared between two blocks would land twice at the same path. That is the
 * distinction `apps/docs/tests/block-duplication.test.ts` is built around:
 * duplication across blocks can be correct, duplication inside one is just
 * duplication.
 *
 * These were three byte-identical copies of `SubHeader`, `Options` and
 * `FilterOption`, plus three near-identical `Bound`s, until that test reported
 * them.
 */

/**
 * The badges are 20px, the height of `Badge` itself, so they read as words in
 * the row's sentence rather than as buttons beside it. They are buttons all
 * the same, and a thumb needs more than 20px: the tappable area runs 10px past
 * the badge above and below, 40px in all, inside the 44px row and short of
 * the next one. `overflow-visible` because `Button` clips, and would clip
 * this too.
 */
/**
 * A badge inside a `GROUP` box. The badge's own `secondary` reads on the
 * sheet, as in a step's header, but a light-mode box is `muted` — the same
 * grey — so inside one it turns white, the way the box's rows lift off it.
 */
const IN_GROUP = "bg-background dark:bg-secondary";

const BADGE =
  "h-5 overflow-visible rounded-full px-2 font-normal after:absolute after:inset-x-0 after:-inset-y-2.5 after:content-['']";

/**
 * Every filter sheet — the drawer and the operator sheet stacked on it — is
 * one fixed height rather than the height of what it holds.
 *
 * Fitted to its content, a four-row step sat low on the screen with the table
 * looming over it, and the sheet jumped in height at every drill. Fixed, it
 * stays put from step to step, and two stacked sheets line up exactly, the one
 * behind peeking out by the stack's offset alone. 80dvh is the drawer's own
 * cap. A `className`, so it wins over the stack's layered height rule.
 */
export const FILTER_SHEET = "h-[80dvh]";

/** A filter's operator, as the drawer shows it: what it reads, and a way in. */
export interface OperatorHandle {
  label: string;
  onOpen: () => void;
}

/**
 * The operator as a badge — `Player [contains ⌄]` — opening the operator
 * sheet. The same control in a step's header and in an applied filter's row,
 * so the comparison is changed the same way wherever it is read.
 */
export function OperatorBadge({
  dimension,
  inGroup = false,
  operator,
}: {
  /** Sitting in a `GROUP` box rather than on the sheet. */
  inGroup?: boolean;
  /** The filter it belongs to, for the accessible name. */
  dimension: string;
  operator: OperatorHandle;
}) {
  return (
    <Button
      aria-haspopup="dialog"
      aria-label={`${dimension} condition: ${operator.label}`}
      className={`shrink-0 gap-0.5 ${BADGE} ${inGroup ? IN_GROUP : ""}`}
      onClick={operator.onOpen}
      size="xs"
      variant="secondary"
    >
      {operator.label}
      <ChevronDownIcon className="size-3 text-muted-foreground" />
    </Button>
  );
}

/**
 * A drawer step's header: the way back to the menu, the filter's name with
 * its operator beside it, and — on a step whose value takes more than one tap
 * to undo — a `Clear`.
 *
 * The operator sits by the title rather than above the values because it is
 * part of the title's sentence, `Player contains`, and it hands the values the
 * height a segmented row used to take. Pass `onClear` only while the filter
 * holds a value: a `Clear` that clears nothing is a control that does nothing.
 */
export function StepHeader({
  onBack,
  onClear,
  operator,
  title,
}: {
  onBack: () => void;
  onClear?: () => void;
  operator?: OperatorHandle;
  title: string;
}) {
  return (
    <DrawerHeader>
      <div className="flex items-center gap-2">
        <Button
          aria-label="Back"
          className="-ml-1"
          onClick={onBack}
          size="icon-xs"
          variant="ghost"
        >
          <ArrowLeftIcon className="size-4" />
        </Button>
        <DrawerTitle>{title}</DrawerTitle>
        {operator ? (
          <OperatorBadge dimension={title} operator={operator} />
        ) : null}
        {onClear ? (
          <Button
            aria-label={`Clear ${title} filter`}
            className="-mr-2 ml-auto"
            onClick={onClear}
            size="xs"
            variant="ghost"
          >
            Clear
          </Button>
        ) : null}
      </div>
    </DrawerHeader>
  );
}

/**
 * The operator picker: a drawer stacked on the filter drawer, one radio row
 * per operator, closing on the pick.
 *
 * A sheet rather than a menu: a menu is a popup sized for a pointer, sitting
 * inside a sheet; this is the phone's own idiom for one of several, with 44px
 * rows and the drawer it came from still showing behind it. Render it inside
 * the filter drawer's content — that is what makes it nest.
 */
/** The pause between picking an operator and its sheet closing. */
const SELECT_BEAT_MS = 120;

export function OperatorSheet({
  onOpenChange,
  onSelect,
  open,
  options,
  title,
  value,
}: {
  onOpenChange: (open: boolean) => void;
  onSelect: (value: string) => void;
  open: boolean;
  options: readonly { label: string; value: string }[];
  title: string;
  value: string;
}) {
  return (
    <Drawer onOpenChange={onOpenChange} open={open}>
      <DrawerContent className={FILTER_SHEET}>
        <div className="w-full">
          {/* The step's header, so the stacked sheet reads as one more step
              with a way back, rather than a dead end you swipe away. */}
          <StepHeader onBack={() => onOpenChange(false)} title={title} />
          <Options
            onValueChange={(next) => {
              onSelect(next);
              // A beat for the radio to fill before the sheet slides away,
              // so the pick is seen to land on the row you meant.
              window.setTimeout(() => onOpenChange(false), SELECT_BEAT_MS);
            }}
            value={value}
          >
            {options.map((option) => (
              <FilterOption
                key={option.value}
                label={option.label}
                value={option.value}
              />
            ))}
          </Options>
        </div>
      </DrawerContent>
    </Drawer>
  );
}

/**
 * How long a collapse takes, and so how long a removed row waits before it is
 * actually removed. The `--duration-base` token's 180ms, read in JS too.
 */
export const COLLAPSE_MS = 180;

/**
 * Opens and closes its content by its own height: `grid-template-rows` from
 * `1fr` to `0fr`, with opacity, so whatever sits below slides rather than
 * jumping. CSS rather than a JS height animation — the browser interpolates
 * `fr` rows itself — and on the duration tokens, so reduced motion makes it
 * instant along with everything else. Closed content stays mounted and goes
 * `inert`, out of the tab order and the accessibility tree.
 */
export function Collapse({
  children,
  open,
}: {
  children: ReactNode;
  open: boolean;
}) {
  // Clipped only while it moves. Left on, `overflow: hidden` also cuts off
  // whatever reaches past the edge of open content — a 32px select in a 30px
  // calendar caption lost its top border, and an edge focus ring would too.
  const [settled, setSettled] = useState(open);
  useEffect(() => {
    if (!open) {
      setSettled(false);
    }
  }, [open]);

  return (
    <div
      className={`grid transition-[grid-template-rows,opacity] duration-(--duration-base) ease-(--ease-ks-out) ${open ? "grid-rows-[1fr] opacity-100" : "grid-rows-[0fr] opacity-0"}`}
      data-collapse={open ? "open" : "closed"}
      inert={!open}
      onTransitionEnd={(event) => {
        if (event.target === event.currentTarget && open) {
          setSettled(true);
        }
      }}
    >
      <div
        className={`min-h-0 ${open && settled ? "overflow-visible" : "overflow-hidden"}`}
      >
        {children}
      </div>
    </div>
  );
}

/** A labelled group of rows in the drawer's menu: `Applied filters`. */
export function DrawerSection({
  children,
  label,
}: {
  children: ReactNode;
  label: string;
}) {
  return (
    <section aria-label={label}>
      <h3 className="px-7 pt-3 pb-1.5 font-medium text-muted-foreground text-xs">
        {label}
      </h3>
      {children}
    </section>
  );
}

/**
 * One applied filter, as a sentence: `Currency [is not] [BTC, ETH] ✕`.
 *
 * The value opens the filter's step, the operator its sheet, the ✕ clears it.
 * A filter without operators has no badge for one — a badge that looks
 * tappable and does nothing would be the one dead control on the screen.
 */
export function AppliedRow({
  label,
  onEdit,
  onRemove,
  operator,
  value,
}: {
  label: string;
  onEdit: () => void;
  onRemove: () => void;
  operator?: OperatorHandle;
  /** `null` for an operator with nothing beside it: `Created [is empty]`. */
  value: string | null;
}) {
  return (
    <div
      className="flex h-11 items-center gap-2 px-3"
      data-applied-filter={label}
    >
      <span className="shrink-0 font-medium text-sm">{label}</span>
      {operator ? (
        <OperatorBadge dimension={label} inGroup operator={operator} />
      ) : null}
      {value === null ? null : (
        <Button
          aria-label={`${label}: ${value}`}
          className={`min-w-0 justify-start ${BADGE} ${IN_GROUP}`}
          onClick={onEdit}
          size="xs"
          variant="secondary"
        >
          <span className="min-w-0 truncate">{value}</span>
        </Button>
      )}
      <Button
        aria-label={`Remove ${label} filter`}
        className="-mr-2 ml-auto shrink-0"
        onClick={onRemove}
        size="icon-sm"
        variant="ghost"
      >
        <XIcon className="size-4" />
      </Button>
    </div>
  );
}

/**
 * One row of the drilldown menu: what it filters, and a chevron saying it
 * opens. A filter's value is not repeated here — the applied section above is
 * where the menu says what is set, and one fact in two places can disagree.
 * `value` is for rows that are not filters, like Sort.
 */
export function DrilldownRow({
  label,
  onClick,
  value,
}: {
  label: string;
  onClick: () => void;
  value?: string;
}) {
  return (
    <button
      className="flex h-11 w-full cursor-pointer items-center justify-between gap-3 px-3 text-left active:text-muted-foreground"
      onClick={onClick}
      type="button"
    >
      <span className="font-medium text-sm">{label}</span>
      <span className="ml-auto inline-flex min-w-0 items-center gap-2 text-muted-foreground text-sm">
        {value ? <span className="truncate">{value}</span> : null}
        <ChevronRightIcon className="size-4 shrink-0" />
      </span>
    </button>
  );
}

/**
 * A list of rows as one rounded box, inset from the sheet's edges — the
 * phone's grouped list. The box says which rows belong together under a
 * section's heading, and the dividers stop at its edge, so they read as
 * separators within a group rather than as rules across the whole sheet.
 *
 * The fill is a step off the sheet's `popover` either way, but which way
 * differs: in light the sheet is white, so the box is `muted` and its badges
 * go back to white on it; in dark the sheet is already a mid surface, so the
 * box is half of `muted` and the `secondary` badges sit a step above it.
 * `w-auto` because `RadioGroup` ships `w-full`, which beside `mx-4` pushed
 * the box 32px past the sheet's right edge.
 * Light-mode `muted/50` on white was all but invisible, and so were the
 * badges on it.
 */
export const GROUP =
  "mx-4 w-auto divide-y divide-border-muted overflow-hidden rounded-xl bg-muted dark:bg-muted/50";

/** The list wrapper the drilldown rows sit in. */
export function DrilldownList({ children }: { children: ReactNode }) {
  return <div className={GROUP}>{children}</div>;
}

/** A radio list styled as drawer rows rather than as a form control group. */
export function Options({
  children,
  onValueChange,
  value,
}: {
  children: ReactNode;
  onValueChange: (value: string) => void;
  value: string;
}) {
  return (
    <div className="pb-4">
      <RadioGroup
        className={`gap-0 ${GROUP}`}
        onValueChange={(next) => {
          if (next) {
            onValueChange(next as string);
          }
        }}
        value={value}
      >
        {children}
      </RadioGroup>
    </div>
  );
}

export function FilterOption({
  label,
  value,
}: {
  label: string;
  value: string;
}) {
  return (
    // biome-ignore lint/a11y/noLabelWithoutControl: control is inside label
    <label className="flex h-11 cursor-pointer items-center gap-3 px-3">
      <RadioGroupItem value={value} />
      <span className="text-sm">{label}</span>
    </label>
  );
}

/**
 * One end of a range. `type` defaults to text because most bounds are numeric
 * strings; the date filters pass `type="date"`.
 */
export function Bound({
  id,
  label,
  onChange,
  placeholder,
  type = "text",
  value,
}: {
  id: string;
  label: string;
  onChange: (value: string) => void;
  placeholder?: string;
  type?: string;
  value: string;
}) {
  return (
    <div className="flex flex-col gap-1.5">
      <Label className="text-muted-foreground" htmlFor={id}>
        {label}
      </Label>
      <Input
        id={id}
        inputMode={type === "text" ? "decimal" : undefined}
        onChange={(event) => onChange(event.target.value)}
        placeholder={placeholder}
        // The filter surfaces are dense screens, so `sm` (32px) like the
        // toolbar they belong to. Touch keeps 16px text at either size, so
        // iOS does not zoom on focus.
        size="sm"
        type={type}
        value={value}
      />
    </div>
  );
}

/**
 * A set filter's values as checkboxes: Status, Currency. Checkboxes, not
 * radios, so it is the one kind of screen you do not leave per pick.
 */
export function SetChecklist<T extends string>({
  items,
  label,
  onChange,
  value,
}: {
  items: readonly T[];
  label: (item: T) => string;
  onChange: (next: T[]) => void;
  value: readonly T[];
}) {
  return (
    <div className="pb-4">
      <div className={GROUP}>
        {items.map((item) => (
          // biome-ignore lint/a11y/noLabelWithoutControl: control is inside label
          <label
            className="flex h-11 cursor-pointer items-center gap-3 px-3"
            key={item}
          >
            <Checkbox
              checked={value.includes(item)}
              onCheckedChange={() =>
                onChange(
                  value.includes(item)
                    ? value.filter((held) => held !== item)
                    : [...value, item]
                )
              }
            />
            <span className="text-sm">{label(item)}</span>
          </label>
        ))}
      </div>
    </div>
  );
}

/**
 * A menu row that does something rather than opening a step — Export — so it
 * ends in what it does, not a chevron.
 */
export function ActionRow({
  disabled = false,
  label,
  onClick,
  value,
}: {
  disabled?: boolean;
  label: string;
  onClick: () => void;
  value?: string;
}) {
  return (
    <button
      className="flex h-11 w-full cursor-pointer items-center justify-between gap-3 px-3 text-left active:text-muted-foreground disabled:cursor-not-allowed disabled:opacity-50"
      disabled={disabled}
      onClick={onClick}
      type="button"
    >
      <span className="font-medium text-sm">{label}</span>
      <span className="ml-auto inline-flex min-w-0 items-center gap-2 text-muted-foreground text-sm">
        {value ? <span className="truncate">{value}</span> : null}
        <DownloadIcon className="size-4 shrink-0" />
      </span>
    </button>
  );
}

/**
 * What the drawer needs to offer the toolbar's view controls — Columns and
 * Export — which the desktop keeps at the toolbar's far end and a phone has
 * no room for. Handed down by the toolbar, which owns the table; the drawer
 * stays out of table state.
 */
export interface DrawerView<C extends string> {
  columns: readonly { id: C; label: string }[];
  /** Off while a request is in flight, or a tap would export the old rows. */
  exportDisabled: boolean;
  hiddenColumns: ReadonlySet<C>;
  onExport: () => void;
  onToggleColumn: (id: C) => void;
  /** How many rows an export writes: every filtered row, not the page. */
  rowCount: number;
}

/**
 * The menu's last section: how the rows are shown, not which — Sort, Columns,
 * Export — apart from the filters, as the desktop keeps them apart.
 */
export function ViewSection<C extends string>({
  onColumns,
  onSort,
  sortValue,
  view,
}: {
  onColumns: () => void;
  onSort: () => void;
  sortValue: string;
  view: DrawerView<C>;
}) {
  const shown = view.columns.filter(
    (column) => !view.hiddenColumns.has(column.id)
  ).length;
  return (
    <DrawerSection label="View">
      <DrilldownList>
        <DrilldownRow label="Sort" onClick={onSort} value={sortValue} />
        <DrilldownRow
          label="Columns"
          onClick={onColumns}
          value={`${shown} of ${view.columns.length}`}
        />
        <ActionRow
          disabled={view.exportDisabled}
          label="Export"
          onClick={view.onExport}
          value={`${view.rowCount} ${view.rowCount === 1 ? "row" : "rows"}`}
        />
      </DrilldownList>
    </DrawerSection>
  );
}

/** The Columns step: the desktop menu's columns, as checkboxes. */
export function ColumnChecklist<C extends string>({
  view,
}: {
  view: DrawerView<C>;
}) {
  const labels = new Map(
    view.columns.map((column) => [column.id, column.label])
  );
  return (
    <SetChecklist
      items={view.columns.map((column) => column.id)}
      label={(id) => labels.get(id) ?? id}
      onChange={(next) => {
        // A checklist reports the whole set; the table toggles one column.
        const changed = view.columns.find(
          (column) =>
            next.includes(column.id) === view.hiddenColumns.has(column.id)
        );
        if (changed) {
          view.onToggleColumn(changed.id);
        }
      }}
      value={view.columns
        .filter((column) => !view.hiddenColumns.has(column.id))
        .map((column) => column.id)}
    />
  );
}
